-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;sylphe&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Inflige +1 d&#233;g&#226;t de l&#39;&#233;nergie li&#233;e &#224; la race du personnage&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sang-De-Nain.html&quot; title=&quot;Sang de nain&quot;&gt;Sang de nain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain des traits raciaux nains lentement mais s&#251;rement et connaissances de la pierre&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saut-&#201;l&#233;mentaire.html&quot; title=&quot;Saut &#233;l&#233;mentaire&quot;&gt;Saut &#233;l&#233;mentaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ifrit-(Race).html&quot; title=&quot;Les ifrits&quot;&gt;Ifrit&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;sylphe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;ondin&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;or&#233;ade&lt;/a&gt;, niveau 15&lt;/td&gt;&lt;td&gt;Le personnage peut lancer &lt;i&gt;changement de plan&lt;/i&gt; 1 fois par jour pour retourner sur le plan de ses anc&#234;tres&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semelle-De-Pierre.html&quot; title=&quot;Semelle de pierre&quot;&gt;Semelle de pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Ignore les terrains difficiles de terre et de pierre&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Fouisseur-Or&#233;ade.html&quot; title=&quot;Fouisseur or&#233;ade&quot;&gt;Fouisseur or&#233;ade&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Semelle-De-Pierre.html&quot; title=&quot;Semelle de pierre&quot;&gt;semelle de pierre&lt;/a&gt;, niveau 9&lt;/td&gt;&lt;td&gt;Gain d&#39;une vitesse de creusement&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-Nageur-De-Terre.html&quot; title=&quot;Or&#233;ade nageur de terre&quot;&gt;Or&#233;ade nageur de terre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Semelle-De-Pierre.html&quot; title=&quot;Semelle de pierre&quot;&gt;semelle de pierre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Fouisseur-Or&#233;ade.html&quot; title=&quot;Fouisseur or&#233;ade&quot;&gt;Fouisseur or&#233;ade&lt;/a&gt;, niveau 13&lt;/td&gt;&lt;td&gt;Gain de la capacit&#233; nage dans la terre&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
